{
  "mechanism": {
    "summary": "A tokenizer is the only part of the pipeline that touches raw text: it maps text to integers the model can use, and maps the model's integers back to text. Its vocabulary is learned from a corpus by repeatedly merging the most frequent neighbouring pair of symbols, starting from raw bytes. Encoding new text first splits it into pre-token chunks and then replays those merges in the order they were learned, so a frequent word collapses into one token while a rare word stays in pieces.",
    "sourceChunkIds": [
      "source-1#chunk-1",
      "source-1#chunk-2",
      "source-1#chunk-3",
      "source-2#chunk-1"
    ],
    "steps": [
      {
        "text": "Pre-tokenization splits text into chunks: letters stay together, punctuation is split off, a space stays with the word that follows it, and digits are split one at a time. Merges never cross a chunk border.",
        "sourceChunkIds": [
          "source-2#chunk-1"
        ]
      },
      {
        "text": "Each chunk is read as raw bytes. The starting alphabet is the set of possible byte values, so any text at all can be written and nothing is ever unknown.",
        "sourceChunkIds": [
          "source-1#chunk-2",
          "source-2#chunk-1"
        ]
      },
      {
        "text": "During vocabulary training, count every pair of neighbouring symbols across the whole corpus.",
        "sourceChunkIds": [
          "source-1#chunk-2"
        ]
      },
      {
        "text": "Take the most frequent pair, for example the pair forming a common letter combination, and add it to the vocabulary as one new symbol.",
        "sourceChunkIds": [
          "source-1#chunk-2"
        ]
      },
      {
        "text": "Replace that pair everywhere in the corpus with the new symbol, then count again. Repeat until the vocabulary reaches its target size.",
        "sourceChunkIds": [
          "source-1#chunk-2"
        ]
      },
      {
        "text": "The order of merges becomes part of the tokenizer: early merges join very common pairs, late merges build whole common words and word endings.",
        "sourceChunkIds": [
          "source-1#chunk-2"
        ]
      },
      {
        "text": "To encode new text, split it into bytes and replay the learned merges in the order they were learned, joining every pair it can.",
        "sourceChunkIds": [
          "source-1#chunk-3"
        ]
      },
      {
        "text": "A common word comes out as a single token; an unusual word stays in several pieces because no merge ever joined them.",
        "sourceChunkIds": [
          "source-1#chunk-3"
        ]
      },
      {
        "text": "The model looks each id up in its embedding table, which has one row per vocabulary entry, and produces ids on the way out.",
        "sourceChunkIds": [
          "source-1#chunk-1",
          "source-1#chunk-3"
        ]
      },
      {
        "text": "Decoding maps ids back to pieces and bytes, returning exactly the original text, including spaces, line breaks and emoji.",
        "sourceChunkIds": [
          "source-2#chunk-1"
        ]
      }
    ]
  },
  "plainSummary": "A tokenizer turns text into whole numbers, one per small piece called a token. It learns pieces from a big text sample, starting from bytes, the raw storage units. It repeatedly merges the most common neighbouring pair into one new piece. Frequent words become one token; rare words stay in several pieces. New text is split by fixed rules, then the same merges are replayed in order.",
  "analogies": [
    {
      "analogy": "A note-taker invents shorthand: first a squiggle for the most common letter pair, then squiggles for common word endings, and finally whole squiggles for the words that come up most.",
      "matches": "The merge loop adds the most frequent neighbouring pair as a new symbol first, then later merges build whole common words and word endings; encoding replays that same list in the same order.",
      "breaksDown": "A human note-taker invents new shortcuts on the fly and reads them back from context. The tokenizer's merge list is fixed once learned and applied in one exact order, so it cannot adapt to a new document."
    },
    {
      "analogy": "A print shop keeps a stamp for every common word, plus single-character stamps in reserve, so even a name nobody has printed before can be set.",
      "matches": "Starting the vocabulary from the raw byte values means any text can be written out of small pieces, so an unseen word is spelled from pieces instead of failing.",
      "breaksDown": "The reserve unit is a byte, not a character: one emoji or accented letter takes several byte stamps, and in this library stamps also never reach across a space or a digit boundary."
    }
  ],
  "glossary": [
    {
      "term": "tokenizer",
      "plainMeaning": "The component that turns text into the integers a model reads, and turns the model's integers back into text.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ]
    },
    {
      "term": "token",
      "plainMeaning": "One piece of text that maps to one integer id; it can be a whole word, a word part, or a byte.",
      "sourceChunkIds": [
        "source-1#chunk-1",
        "source-2#chunk-1"
      ]
    },
    {
      "term": "vocabulary",
      "plainMeaning": "The fixed list of pieces the tokenizer can output, each with its own id.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ]
    },
    {
      "term": "merge",
      "plainMeaning": "A learned rule that joins two neighbouring symbols into one new symbol, applied in the order it was learned.",
      "sourceChunkIds": [
        "source-1#chunk-2"
      ]
    },
    {
      "term": "byte-level",
      "plainMeaning": "Starting from raw bytes instead of letters, so any text can be represented and no text is unknown.",
      "sourceChunkIds": [
        "source-1#chunk-2",
        "source-2#chunk-1"
      ]
    },
    {
      "term": "pre-tokenization",
      "plainMeaning": "The fixed splitting rules applied before merges; merges never join pieces across these split points.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ]
    },
    {
      "term": "special tokens",
      "plainMeaning": "Reserved ids the application adds to mark things like start, end or padding; they are never produced from ordinary text.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ]
    },
    {
      "term": "round trip",
      "plainMeaning": "Decoding an encoded text gives back exactly the original text, spaces, line breaks and emoji included.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ]
    },
    {
      "term": "embedding table",
      "plainMeaning": "The model's table with one row of numbers per vocabulary entry, which every token id is looked up in.",
      "sourceChunkIds": [
        "source-1#chunk-3"
      ]
    },
    {
      "term": "context window",
      "plainMeaning": "The maximum amount of text a model can consider at once, measured in tokens.",
      "sourceChunkIds": [
        "source-3#chunk-1"
      ]
    }
  ],
  "facts": [
    {
      "id": "fact-1",
      "statement": "A language model never sees letters: a tokenizer turns text into a list of integers, one per token, and on the way out turns the model's integers back into text.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-2",
      "statement": "Everything the model knows about spelling it must learn from which pieces of text share which integers.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-3",
      "statement": "The vocabulary of Saltmarsh, the guide's tokenizer, has 32,000 entries.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-4",
      "statement": "Cutting text into single characters keeps the vocabulary tiny, but a paragraph becomes thousands of steps long and the model must spend its fixed context on spelling.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-5",
      "statement": "Cutting text into whole words keeps sequences short, but the vocabulary explodes because every name, typo and new word needs an entry, and a word never seen in training has no integer at all.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-6",
      "statement": "Subword tokenizers sit between characters and words: frequent words get a single token of their own, and rare words are spelled out from smaller pieces the vocabulary does have.",
      "sourceChunkIds": [
        "source-1#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-7",
      "statement": "The vocabulary is learned by starting from the 256 possible byte values, counting every neighbouring pair across the corpus, adding the most frequent pair as a new symbol, replacing that pair everywhere, and repeating until the target vocabulary size is reached.",
      "sourceChunkIds": [
        "source-1#chunk-2"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-8",
      "statement": "The order of the merges is part of the tokenizer: early merges join very common pairs, late merges build whole common words and word endings.",
      "sourceChunkIds": [
        "source-1#chunk-2"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-9",
      "statement": "Encoding splits new text into bytes, then replays the learned merges in the order they were learned, joining every pair it can.",
      "sourceChunkIds": [
        "source-1#chunk-3"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-10",
      "statement": "A common word such as \"the\" collapses into one token, while an unusual word stays in several pieces because no merge ever joined those pieces.",
      "sourceChunkIds": [
        "source-1#chunk-3"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-11",
      "statement": "A larger vocabulary makes sequences shorter because more text fits in each token, but every entry needs its own row in the embedding table and rare entries are seen too seldom during training to be learned well; a smaller vocabulary is cheaper to store but makes sequences longer.",
      "sourceChunkIds": [
        "source-1#chunk-3"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-12",
      "statement": "On Saltmarsh's English test set one token covers about 4 characters of text on average, and the guide warns that this ratio is a property of English prose, not of tokenizers.",
      "sourceChunkIds": [
        "source-1#chunk-3"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-13",
      "statement": "glyphcut works on bytes, so it never needs an unknown token, and decoding an encoded text returns exactly the original text including spaces, line breaks and emoji.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-14",
      "statement": "glyphcut is deterministic: the same text and the same vocabulary always give the same ids.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-15",
      "statement": "Pre-tokenization splits text into chunks that merges never cross: letters stay together, punctuation is split off, and a space is kept at the start of the word that follows it, so a word with its leading space and the same word at the start of a line are two different tokens with two different ids.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-16",
      "statement": "Digits are split one at a time, so a long number becomes one token per digit, which keeps the vocabulary from spending entries on arbitrary numbers.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-17",
      "statement": "Special tokens such as start, end and padding markers are reserved ids added by the application and never produced by encoding ordinary text, so a user cannot type them.",
      "sourceChunkIds": [
        "source-2#chunk-1"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-18",
      "statement": "A count function returns the number of tokens without building the id list, and only the tokenizer the model was trained with gives the true number; ids from one model's tokenizer mean nothing to another model.",
      "sourceChunkIds": [
        "source-2#chunk-2"
      ],
      "confidence": "high"
    },
    {
      "id": "fact-19",
      "statement": "Capital letters, leading spaces and rare spellings change how a word splits: a name with a capital, the same name after a space, and the all-caps form can be one, one and three tokens.",
      "sourceChunkIds": [
        "source-2#chunk-2"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-20",
      "statement": "At the support-chat company Corrowby every request to the language model is billed by the token and every conversation must fit the model's context window, also measured in tokens; for a year they estimated both from word counts.",
      "sourceChunkIds": [
        "source-3#chunk-1"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-21",
      "statement": "For Corrowby's English support replies one word came to about 1.3 tokens on average: short common words are one token each, while product names, long words and anything with unusual capitals split into several.",
      "sourceChunkIds": [
        "source-3#chunk-1"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-22",
      "statement": "The same translated support answers in a language that was rare in the tokenizer's training text needed about 3 times as many tokens, because its words had few merges of their own and were spelled out in small pieces, so the same answer cost three times as much and used three times as much of the context window.",
      "sourceChunkIds": [
        "source-3#chunk-1"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-23",
      "statement": "Source code splits into many tokens because indentation runs of spaces and mixed-case identifiers are broken up, and numbers go digit by digit; the authors believe this is also why the model slips on long arithmetic, since it never sees a number as one thing.",
      "sourceChunkIds": [
        "source-3#chunk-2"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-24",
      "statement": "The often-quoted rule that a token is about four characters held for Corrowby's English text but not for code or the rarer languages, and they have not agreed on a single rule to replace it; some want a per-language table, others want to count every message exactly.",
      "sourceChunkIds": [
        "source-3#chunk-2"
      ],
      "confidence": "medium"
    },
    {
      "id": "fact-25",
      "statement": "Corrowby changed to counting tokens with the exact tokenizer of the model they call, writing prompt and reply budgets in tokens, and producing per-language cost reports.",
      "sourceChunkIds": [
        "source-3#chunk-2"
      ],
      "confidence": "high"
    }
  ],
